def bars():
    W,Hh=520,200; mx=max(yr[y]['rev'] for y in yr)*1.1
    s=f"<svg viewBox='0 0 {W} {Hh}' xmlns='http://www.w3.org/2000/svg' style='direction:ltr;background:#fff;border:1px solid #cfd8c2;border-radius:6px' font-family='DejaVu Sans' font-size='11'>"
    for i,y in enumerate((1,2,3)):
        x=60+i*150; h=yr[y]['rev']/mx*140; n=yr[y]['net']/mx*140
        s+=f"<rect x='{x}' y='{170-h}' width='50' height='{h}' fill='#5f7d52'/><text x='{x+25}' y='{165-h}' text-anchor='middle'>{yr[y]['rev']/1000:,.0f}k</text>"
        s+=f"<rect x='{x+55}' y='{170-max(n,0)}' width='50' height='{abs(n)}' fill='{'#d0a03c' if n>=0 else '#b5523b'}'/><text x='{x+80}' y='{165-max(n,0)}' text-anchor='middle'>{yr[y]['net']/1000:,.0f}k</text>"
        s+=f"<text x='{x+52}' y='188' text-anchor='middle'>Y{y}</text>"
    s+="<text x='20' y='16' fill='#5f7d52'>■ Revenue  </text><text x='110' y='16' fill='#d0a03c'>■ Net profit (OMR)</text></svg>"
    return s
def cashline():
    W,Hh=520,210; allv=[r['cum'] for sc in (base,cons,opt) for r in sc[0]]; lo,hi=min(allv),max(allv)
    X=lambda m:30+(m-1)/35*470; Y=lambda v:15+(hi-v)/(hi-lo)*165
    s=f"<svg viewBox='0 0 {W} {Hh}' xmlns='http://www.w3.org/2000/svg' style='direction:ltr;background:#fff;border:1px solid #cfd8c2;border-radius:6px' font-family='DejaVu Sans' font-size='10'>"
    s+=f"<line x1='30' x2='500' y1='{Y(0)}' y2='{Y(0)}' stroke='#999' stroke-dasharray='3'/>"
    for sc,col,lab in ((cons,'#b5523b','Conservative'),(base,'#5f7d52','Base'),(opt,'#d0a03c','Optimistic')):
        pts=" ".join(f"{X(r['m']):.1f},{Y(r['cum']):.1f}" for r in sc[0]); s+=f"<polyline points='{pts}' fill='none' stroke='{col}' stroke-width='2.5'/>"
    for i,(c,l) in enumerate(((' #b5523b','Conservative'),('#5f7d52','Base'),('#d0a03c','Optimistic'))): s+=f"<text x='{40+i*110}' y='203' fill='{c.strip()}'>■ {l}</text>"
    s+=f"<text x='34' y='{Y(0)-3}' fill='#666'>0</text><text x='260' y='196' fill='#666' text-anchor='middle'>Month 1 → 36 (cumulative cash, OMR)</text></svg>"
    return s
